WITH filtered AS (SELECT id, full_name, email, dept_id, manager_id, job_title, hire_date, is_remote, level, TRIM(email) AS clean_email, COALESCE(full_name, 'N/A') AS full_name_filled, COALESCE(level, 'OTHER') AS level_clean FROM employees WHERE job_title IS DISTINCT FROM 'Analyst') SELECT level, DATE_TRUNC('WEEK', hire_date) AS week_start, SORT_ARRAY(COLLECT_SET(level)) AS level_list, COUNT(*) AS cnt, COUNT(*) FILTER (WHERE job_title = 'Designer') AS designer_rows, COUNT_IF(job_title = 'Designer') AS designer_events FROM filtered GROUP BY ROLLUP (level, DATE_TRUNC('WEEK', hire_date));
